// Soft-remove applicants once their interview date has passed (mirrors rejection):
// hides the evaluation from the UI (application_status='removed') and marks the
// interview 'completed', but KEEPS the applicant, resume, Email_Logs, and Interviews
// rows for the audit trail. Self-contained via the Supabase service key (Audit_Logs +
// Job_Requirements are RLS-blocked for the anon key). Every request guarded so one bad
// row can't halt the run.
const SB = 'https://kzszvpmwvvtfvcgdzgnj.supabase.co';
const KEY = $env.SUPABASE_SERVICE_KEY;
const H  = { apikey: KEY, Authorization: `Bearer ${KEY}` };
const HJ = { ...H, 'Content-Type': 'application/json', Prefer: 'return=minimal' };
function uuidv4(){return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return (c==='x'?r:(r&0x3|0x8)).toString(16);});}
const get  = async (url) => { try { return await this.helpers.httpRequest({ method: 'GET', url, headers: H, json: true }); } catch (e) { return null; } };
const send = async (method, url, body) => { try { await this.helpers.httpRequest({ method, url, headers: HJ, body, json: true }); } catch (e) {} };

// Interviews still marked 'scheduled' whose date is now in the past (meeting is over).
// Filtering on interview_status='scheduled' stops rows being re-processed each run.
const cutoff = new Date().toISOString();
const interviews = (await get(`${SB}/rest/v1/Interviews?select=interview_id,evaluation_id&interview_status=eq.scheduled&interview_date=lt.${cutoff}`)) || [];

let processed = 0;
for (const iv of interviews) {
  const evaluation_id = iv.evaluation_id;
  const interview_id  = iv.interview_id;
  if (!evaluation_id) continue;

  const evs = (await get(`${SB}/rest/v1/Evaluations?select=resume_id,requirement_id,application_status&evaluation_id=eq.${evaluation_id}`)) || [];
  const ev = evs[0] || {};
  // Skip evaluations that are already archived/removed.
  if (ev.application_status === 'removed') {
    await send('PATCH', `${SB}/rest/v1/Interviews?interview_id=eq.${interview_id}`, { interview_status: 'completed' });
    continue;
  }
  const resume_id = ev.resume_id || null;
  const requirement_id = ev.requirement_id || null;
  let applicant_id = null, name = 'An applicant', company_id = null;
  if (resume_id) {
    const rs = (await get(`${SB}/rest/v1/Resumes?select=applicant_id&resume_id=eq.${resume_id}`)) || [];
    applicant_id = rs[0] ? rs[0].applicant_id : null;
  }
  if (applicant_id) {
    const ap = (await get(`${SB}/rest/v1/Applicants?select=full_name&applicant_id=eq.${applicant_id}`)) || [];
    if (ap[0] && ap[0].full_name) name = ap[0].full_name;
  }
  if (requirement_id) {
    const rq = (await get(`${SB}/rest/v1/Job_Requirements?select=company_id&requirement_id=eq.${requirement_id}`)) || [];
    company_id = rq[0] ? rq[0].company_id : null;
  }

  // Permanent audit (applicant is KEPT, so the applicant_id link is valid).
  if (company_id) {
    await send('POST', `${SB}/rest/v1/Audit_Logs`, {
      audit_log_id: uuidv4(),
      applicant_id: applicant_id,
      requirement_id: requirement_id || null,
      action_type: 'INTERVIEW_COMPLETED',
      action_details: `[c:${company_id}] ${name}'s interview date has passed; they were removed from the active list.`,
    });
  }

  // Soft-delete: hide from the UI + mark the interview done (no data deleted).
  await send('PATCH', `${SB}/rest/v1/Evaluations?evaluation_id=eq.${evaluation_id}`, { application_status: 'removed' });
  await send('PATCH', `${SB}/rest/v1/Interviews?interview_id=eq.${interview_id}`, { interview_status: 'completed' });
  processed++;
}
return [{ json: { checked: interviews.length, processed } }];
